from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
manifest=json.loads((ROOT/'build/manifest.json').read_text())
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Blueprint 06 · 프레젠테이션</title><style>*{box-sizing:border-box}body{margin:0;background:#f1f3f8;color:#172343;font:14px system-ui,sans-serif}header{height:76px;padding:0 32px;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid #d9e0ed}h1{font-size:21px;letter-spacing:-.5px;margin:0}header small{display:block;margin-top:5px;color:#72809b;font-size:12px}.controls{display:flex;gap:8px;align-items:center}select,button,a.btn{font:inherit;border:1px solid #cdd6e7;padding:9px 12px;background:#fff;color:#233d74;border-radius:7px;text-decoration:none;cursor:pointer}button.active{background:#3157d4;color:#fff;border-color:#3157d4}.layout{display:grid;grid-template-columns:228px 1fr;height:calc(100vh - 76px)}aside{overflow:auto;background:#fff;border-right:1px solid #d9e0ed;padding:16px}aside button{display:block;width:100%;text-align:left;border:0;border-radius:6px;margin-bottom:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:10px}aside button span{font-size:11px;color:#7b879e;margin-right:7px}main{overflow:auto;padding:28px 32px}.stage{max-width:1280px;margin:auto;aspect-ratio:16/9;position:relative;background:white;box-shadow:0 8px 30px #1c2d6112;overflow:hidden}.stage iframe{border:0;width:1280px;height:720px;transform-origin:top left}.stage img{width:100%;height:100%;display:block}.caption{max-width:1280px;margin:15px auto;display:flex;justify-content:space-between;color:#6a7893}.help{max-width:1280px;margin:25px auto 0;line-height:1.8;color:#66738a;font-size:12px}.links{max-width:1280px;margin:25px auto;display:flex;gap:10px;flex-wrap:wrap}.compare{display:none;max-width:1280px;margin:24px auto}.compare img{width:100%;display:block}.compare.open{display:block}@media(max-width:800px){header{height:auto;padding:18px;display:block}.controls{margin-top:12px;flex-wrap:wrap}.layout{grid-template-columns:150px 1fr}main{padding:14px}aside{padding:8px}}</style><header><div><h1>Blueprint 06</h1><small>6개 덱 · 115개 참고 슬라이드 · 31개 Rhetis 요소</small></div><div class="controls"><select id="deck"></select><button data-mode="replica" class="active">원본 재현</button><button data-mode="assembly">컬렉션 재조립</button><button data-mode="reference">참고 이미지</button><button id="pair">좌우 비교</button></div></header><div class="layout"><aside id="slides"></aside><main><div class="stage" id="stage"></div><div class="caption"><span id="caption"></span><span>1280 × 720 · ← → 이동</span></div><div class="compare" id="compare"></div><div class="links"><a class="btn" href="pdfs/replica-all.pdf">재현 전체 PDF</a><a class="btn" href="pdfs/assembly-all.pdf">재조립 전체 PDF</a><a class="btn" href="pdfs/replica-sheets.pdf">재현 모아보기 PDF</a><a class="btn" href="build/library/light.html">라이브러리 Light</a><a class="btn" href="build/library/dark.html">라이브러리 Dark</a><a class="btn" href="review/final-review.md">검수 기록</a></div><p class="help">사진·복잡한 삽화·기기 화면은 연회색 placeholder입니다. 원본 재현은 원래 배치와 타이포에 맞춘 HTML/CSS이며, 컬렉션 재조립은 동일 핵심 내용을 계약 요소로 다시 구성한 버전입니다. 참고 이미지는 비교 모드에서만 표시됩니다. 코드·폰트·도형은 로컬 파일로 동작합니다.</p></main></div><script>const manifest=__DATA__;let current=manifest[0],index=0,mode='replica',pair=false;const q=x=>document.querySelector(x),deck=q('#deck'),stage=q('#stage');manifest.forEach(d=>{const o=document.createElement('option');o.value=d.id;o.textContent=d.id+' · '+d.title+' ('+d.slides.length+')';deck.append(o)});deck.onchange=()=>{current=manifest.find(d=>d.id===deck.value);index=0;drawList();draw()};function drawList(){q('#slides').replaceChildren();current.slides.forEach((s,i)=>{let b=document.createElement('button');b.textContent=s.id.replace('slide_','')+'  '+s.title;b.onclick=()=>{index=i;draw()};q('#slides').append(b)})}function resize(){let f=stage.querySelector('iframe');if(f)f.style.transform='scale('+stage.clientWidth/1280+')'}function draw(){let s=current.slides[index];stage.replaceChildren();let node=document.createElement(mode==='reference'?'img':'iframe');node.src=mode==='reference'?'references/'+current.id+'/'+s.id+'.png':'build/'+mode+'/'+current.id+'/'+s.id+'.html';node.title=s.title;stage.append(node);q('#caption').textContent=current.id+' / '+s.id+' · '+s.title;[...q('#slides').children].forEach((b,i)=>b.classList.toggle('active',i===index));q('#compare').classList.toggle('open',pair);q('#compare').innerHTML=pair?'<img alt="원본과 결과 좌우 비교" src="comparisons/final/'+(mode==='reference'?'replica':mode)+'/'+current.id+'/'+s.id+'.jpg">':'';resize()}document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(c=>c.classList.toggle('active',c===b));draw()});q('#pair').onclick=()=>{pair=!pair;q('#pair').classList.toggle('active',pair);draw()};window.onresize=resize;window.onkeydown=e=>{if(e.key==='ArrowRight'){index=Math.min(index+1,current.slides.length-1);draw()}if(e.key==='ArrowLeft'){index=Math.max(0,index-1);draw()}};drawList();draw()</script></html>'''
(ROOT/'index.html').write_text(html.replace('__DATA__',json.dumps(manifest,ensure_ascii=False)))
print('Interactive preview generated')
